\text{Let } a, b, c \text{ be positive real numbers satisfying the following conditions:} 
\begin{cases}
\frac{1}{\sqrt{2}} \leq c < \frac{1}{2} \min\{a\sqrt{2},\ b\sqrt{3}\}, \\
 a + c\sqrt{3} \geq \sqrt{6}, \\
 b\sqrt{3} + c\sqrt{10} \geq 2\sqrt{5}.
\end{cases}
\text{Find the greatest value of the expression:} 
\[ Q(a, b, c) = \frac{1}{a^2} + \frac{2}{b^2} + \frac{3}{c^2} \]

negatives.text:
\text{Let } x, y, z \text{ be positive real numbers satisfying the following conditions:} 
\begin{cases}
\frac{1}{\sqrt{2}} \leq z < \frac{1}{2} \min\{x\sqrt{2},\ y\sqrt{3}\}, \\
 x + z\sqrt{3} \geq \sqrt{6}, \\
 y\sqrt{3} + z\sqrt{10} \leq 2\sqrt{5}.
\end{cases}
\text{Find the greatest value of the expression:} 
\[ P(x, y, z) = \frac{1}{x^2} + \frac{2}{y^2} + \frac{3}{z^2} \]

\text{Let } x, y, z \text{ be positive real numbers satisfying the following conditions:} 
\begin{cases}
\frac{1}{\sqrt{2}} \leq z < \frac{1}{2} \min\{x\sqrt{2},\ y\sqrt{3}\}, \\
 x + z\sqrt{3} \geq \sqrt{6}, \\
 y\sqrt{3} + z\sqrt{10} \geq 2\sqrt{5}.
\end{cases}
\text{Find the greatest value of the expression:} 
\[ P(x, y, z) = \frac{1}{x^2} + \frac{2}{y^2} + \frac{3}{z^2} + 1 \]

positive_text:
\text{Let } M = \{1, 2, \ldots, 2008\}. \text{Each element of } M \text{ is colored using exactly one of three colors: red, blue, or yellow, with all three colors appearing at least once. Define:}
$$
S_1 = \{(x, y, z) \in M^3 \mid x, y, z \text{ are of the same color and } x + y + z \equiv 0 \pmod{2008}\};
$$
$$
S_2 = \{(x, y, z) \in M^3 \mid x, y, z \text{ are of different colors and } x + y + z \equiv 0 \pmod{2008}\}.
$$
\text{Show that } 2|S_1| > |S_2|.\text{ }

